/**
 * Checks if a string is a valid regex pattern.
 * @param value - The string to check
 * @returns True if the string is a valid regex pattern
 * @example
 * isValidRegex('[a-z]+') // => true
 * isValidRegex('.*')     // => true
 * isValidRegex('[')      // => false
 * @since 1.9.0
 */
export function isValidRegex(value: string): boolean {
  try {
    RegExp(value);
    return true;
  } catch {
    return false;
  }
}

