        },
      ),
    );
  });
});

describe('truthyPromiseOrThrow — contract', () => {
  const fn = truthyPromiseOrThrow<unknown>('err');

  it('1 → 1', () => { expect(fn(1)).toBe(1); });
  it('"hello" → "hello"', () => { expect(fn('hello')).toBe('hello'); });
  it('{} → {} (same reference)', () => {
