  it('idempotent: onlyPath(onlyPath(url)) === onlyPath(url)', () => {
    fc.assert(
      fc.property(fc.string(), (str) => {
        expect(onlyPath(onlyPath(str))).toBe(onlyPath(str));
      }),
    );
  });
});

describe('onlyPath — contract', () => {
  it('null returns null', () => {
    expect(onlyPath(null)).toBeNull();
