    expect(range(10, 0, -3)).toEqual([10, 7, 4, 1]);
  });

  it('should return empty array for range(0)', () => {
    expect(range(0)).toEqual([]);
  });

  it('should return empty array for step 0', () => {
    expect(range(1, 5, 0)).toEqual([]);
