        }
      })
    );
  });

  it('identity mapValue preserves all values', () => {
    fc.assert(
      fc.property(plainObject, (obj) => {
        const result = map(obj as Record<string, number>, v => v);
        expect(result).toEqual(obj);
      })
    );
  });
});

