import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import { zip } from './zip';

describe('zip — property-based', () => {
  it('result length equals min of both array lengths', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer()),
        fc.array(fc.integer()),
        (a, b) => {
          expect(zip(a, b)).toHaveLength(Math.min(a.length, b.length));
