    fc.assert(
      fc.property(
        fc.array(fc.integer()),
        fc.array(fc.integer()),
        (a, b) => {
          const zipped = zip(a, b);
          const min = Math.min(a.length, b.length);
          expect(zipped.map(([x]) => x)).toEqual(a.slice(0, min));
        }
      )
    );
  });
});

